"""Quarantine only unrecorded generated bytecode, preserving the recorded runtime closure."""
if not __debug__: raise RuntimeError("Assertions required")
from pathlib import Path
import datetime,hashlib,json,os,runpy,subprocess
ROOT=Path(__file__).resolve().parents[3]
BASE=Path(__file__).resolve().parent
runtime=ROOT/".runtime/casepath-dev-v2"
receipt=runtime/"runtime-boot-receipt.json"
digest=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
expected_receipt="fb9a84c21c19febb910e320d815fa4c75183b5eff9d608bff9fa75eaea27c2b7"
assert digest(receipt)==expected_receipt
doc=json.loads(receipt.read_text());found=[]
def walk(value):
 if isinstance(value,dict):
  if isinstance(value.get("root"),str) and value["root"].endswith("/site-packages") and "roster" in value:found.append(value)
  for child in value.values():walk(child)
 elif isinstance(value,list):
  for child in value:walk(child)
walk(doc)
assert len(found)==1
section=found[0];site=Path(section["root"])
assert site==runtime/"venv/lib/python3.13/site-packages" and not site.is_symlink()
expected={row["path"]:row for row in section["roster"]}
actual={".":site,**{p.relative_to(site).as_posix():p for p in site.rglob("*")}}
assert not set(expected)-set(actual)
validator=runpy.run_path(str(ROOT/"casepath/tools/validate_local_runtime_history.py"))
for name,row in expected.items():validator["validate_closure_entry"](row,actual[name],name,"unchanged recorded runtime "+name)
extra=sorted(set(actual)-set(expected))
assert extra
for name in extra:
 p=actual[name]
 assert not p.is_symlink() and "__pycache__" in Path(name).parts
 assert p.is_dir() or (p.is_file() and p.suffix==".pyc")
roots=sorted(name for name in extra if actual[name].is_dir() and actual[name].name=="__pycache__")
assert roots
for name in extra:assert any(name==r or name.startswith(r+"/") for r in roots)
proof={"contract":"casepath.generated-cache-repair/1","source_commit":"b20685d1670b33b941b1bfcb902638a879c01b93","started_at":datetime.datetime.now(datetime.timezone.utc).isoformat(),"status":"verified_before_move","baseline_receipt_sha256":expected_receipt,"all_recorded_entries_unchanged":True,"recorded_entries":len(expected),"extra_entries":len(extra),"moved_directories":roots,"extra_files":[{"path":name,"sha256":digest(actual[name]),"bytes":actual[name].stat().st_size} for name in extra if actual[name].is_file()],"no_recorded_file_changed":True,"prevention":"All subsequent verification helpers run with PYTHONDONTWRITEBYTECODE=1 and -B."}
out=BASE/"runtime-cache-quarantine";out.mkdir(exist_ok=False)
proof_path=BASE/"runtime-cache-repair.json"
with proof_path.open("x") as f:json.dump(proof,f,indent=2);f.write("\n")
for name in roots:
 source=site/name;target=out/name
 assert source.is_dir() and not source.is_symlink() and not target.exists()
 target.parent.mkdir(parents=True,exist_ok=True)
 os.rename(source,target)
validator["validate_tree_closure"](section,site,"restored runtime site-packages closure")
assert digest(receipt)==expected_receipt
assert subprocess.check_output(["/usr/bin/git","status","--porcelain"],cwd=ROOT,text=True)==""
proof.update(status="passed",finished_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),quarantine=str(out),original_validator_passed=True,boot_history_preserved=True)
temporary=proof_path.with_suffix(".next")
temporary.write_text(json.dumps(proof,indent=2)+"\n");os.replace(temporary,proof_path)
print(json.dumps({key:proof[key] for key in ["status","recorded_entries","extra_entries","all_recorded_entries_unchanged","original_validator_passed","boot_history_preserved","quarantine"]}),flush=True)
